def show_fact():
    return random.choice(facts)

def show_joke():
    return random.choice(jokes)

def draw_diamond(n):
    lines = []
    for i in range(n):
        lines.append(" " * (n - i - 1) + "*" * (2 * i + 1))
    for i in range(n - 2, -1, -1):
        lines.append(" " * (n - i - 1) + "*" * (2 * i + 1))
    return "\n".join(lines)

def draw_tree(n):
    lines = []
    for i in range(n):
        lines.append(" " * (n - i - 1) + "*" * (2 * i + 1))
    lines.append(" " * (n - 2) + "|||")
    lines.append(" " * (n - 2) + "|||")
    return "\n".join(lines)

def draw_heart():
    lines = []
    for y in range(6, -1, -1):
        line = ""
        for x in range(7):
            eq1 = x * x + (y - abs(x)) ** 2
            if eq1 <= 9:
                line += "*"
            else:
                line += " "
        for x in range(7):
            eq2 = (6 - x) * (6 - x) + (y - abs(6 - x)) ** 2
            if eq2 <= 9:
                line += "*"
            else:
                line += " "
        lines.append(line)
    return "\n".join(lines)

def draw_star(n):
    lines = []
    for i in range(n):
        lines.append(" " * (n - i - 1) + "* " * (i + 1))
    for i in range(n - 2, -1, -1):
        lines.append(" " * (n - i - 1) + "* " * (i + 1))
    return "\n".join(lines)

