        print("Mo Tu We Th Fr Sa Su")
        first = datetime.date(y, m, 1).weekday()
        days_in_month = (datetime.date(y, m + 1, 1) - datetime.date(y, m, 1)).days if m < 12 else 31
        line = "   " * first
        for d in range(1, days_in_month + 1):
            line += "{:2d} ".format(d)
