def draw_castle():
    lines = []
    for i in range(5):
        line = ""
        for j in range(10):
            if (i == 0 and j in [0, 4, 5, 9]) or (i == 1 and j in [0, 4, 5, 9]) or (i == 2) or (i == 3) or (i == 4):
                line += "*" * (1 if j not in [2, 3, 7, 8] or i < 2 else 1)
            else:
                line += " "
        lines.append(line)
    return "\n".join(lines)

