def draw_arrow_up(n):
    lines = []
    for i in range(n):
        lines.append(" " * (n - i - 1) + "*" * (2 * i + 1))
    for i in range(n // 2):
        lines.append(" " * (n - 2) + "|||")
    return "\n".join(lines)

def draw_arrow_down(n):
    lines = []
    for i in range(n // 2):
        lines.append(" " * (n - 2) + "|||")
    for i in range(n, 0, -1):
        lines.append(" " * (n - i) + "*" * (2 * i - 1))
    return "\n".join(lines)

def draw_arrow_left(n):
    lines = []
    for i in range(n):
        lines.append(" " * (n - i - 1) + "*" * (i + 1))
    for i in range(n - 2, -1, -1):
        lines.append(" " * (n - i - 1) + "*" * (i + 1))
    return "\n".join(lines)

def draw_arrow_right(n):
    lines = []
    for i in range(n):
        lines.append(" " * (n - 1) + "*" * (i + 1))
    for i in range(n - 2, -1, -1):
        lines.append(" " * (n - 1) + "*" * (i + 1))
    return "\n".join(lines)

